python3 - <<'EOF'
import re
src = open('tests/test_mock_server.py', encoding='utf-8').read()
doc = open('docs/rule-check-flow.md', encoding='utf-8').read()
# map class -> methods, and method -> class
classes = {}
cur = None
for m in re.finditer(r'^class (\w+)\(|:?\n    def (\w+)\(self', src, re.M):
    if m.group(1):
        cur = m.group(1); classes[cur] = set()
    elif m.group(2) and cur:
        classes[cur].add(m.group(2))
method_class = {meth: cls for cls, meths in classes.items() for meth in meths}
pairs = set(re.findall(r'`((?:CheckRulesEntryTests|Status201BehaviorTests|HeaderTemplateTests|PathModeDuplicateTests|DuplicateRouteTests|StartupWaitFlowTests|RequestBodyRulesValidationTests|PrefixMatchingBehaviorTests)\.(\w+))`', doc))
ok = True
for full, meth in sorted(pairs):
    cls = full.split('.')[0]
    if cls not in classes:
        print("MISSING CLASS:", cls); ok=False
    elif meth not in classes[cls]:
        print("MISSING METHOD:", full); ok=False
# Also check helper names exist
for helper in ["run_check_rules", "occupied_local_port", "start_and_wait_exit",
               "assert_check_success", "assert_check_rules_error",
               "CHECK_RULES_VALID_ROUTES", "CHECK_RULES_NO_WAIT_MAX_SECONDS"]:
    if not re.search(rf'^(def |{re.escape(helper)}\s*=)', src, re.M):
        print("MISSING HELPER:", helper); ok=False
print("all references valid" if ok else "ERRORS ABOVE")
EOF
